package com.digitalclinicalsystems.clinicalsync.platform.frontend.infrastructure.persistence.jpa.entities;

import com.digitalclinicalsystems.clinicalsync.platform.frontend.domain.model.valueobjects.ReferenceType;
import com.digitalclinicalsystems.clinicalsync.platform.shared.infrastructure.persistence.jpa.AuditableAbstractPersistenceEntity;
import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;

/**
 * Links an identifier generated by the frontend (for example a UUID) with the
 * identifier the backend assigned to the same record.
 */
@Entity
@Table(name = "external_references", uniqueConstraints = {
        @UniqueConstraint(name = "uk_external_reference", columnNames = {"reference_type", "external_id"}),
        @UniqueConstraint(name = "uk_internal_reference", columnNames = {"reference_type", "internal_id"})
})
@Getter
@NoArgsConstructor
public class ExternalReferencePersistenceEntity extends AuditableAbstractPersistenceEntity {

    @Enumerated(EnumType.STRING)
    @Column(name = "reference_type", length = 20, nullable = false, updatable = false)
    private ReferenceType referenceType;

    @Column(name = "external_id", length = 100, nullable = false, updatable = false)
    private String externalId;

    @Column(name = "internal_id", nullable = false, updatable = false)
    private Long internalId;

    public ExternalReferencePersistenceEntity(ReferenceType referenceType, String externalId, Long internalId) {
        this.referenceType = referenceType;
        this.externalId = externalId;
        this.internalId = internalId;
    }
}
